{
  "passageId": "audio-perceptual-coding",
  "rules": [
    {
      "id": "R1",
      "ruleQuote": "각 소리 크기에 할당되는 비트의 개수가 늘면 소리는 아날로그 원음에 가까워진다.",
      "statement": "각 소리 크기에 할당되는 비트 수가 늘수록 소리는 아날로그 원음에 가까워진다.",
      "variables": [
        {
          "name": "각 소리 크기에 할당되는 비트 수",
          "effect": "비트 수가 늘면 소리가 아날로그 원음에 가까워진다."
        }
      ],
      "scopeQuote": null,
      "statedApplications": [],
      "openSlots": []
    },
    {
      "id": "R2",
      "ruleQuote": "최소가청강도보다 큰 소리는 들을 수 있지만, 작은 소리는 들을 수 없다.",
      "statement": "조용할 때 소리 크기가 최소가청강도보다 크면 들을 수 있고, 작으면 들을 수 없다.",
      "variables": [
        {
          "name": "최소가청강도에 대한 소리 크기의 대소 관계",
          "effect": "최소가청강도보다 크면 들을 수 있고, 작으면 들을 수 없다."
        }
      ],
      "scopeQuote": "최소가청강도는 조용할 때 청각이 감지할 수 있는 소리 크기의 최솟값이다.",
      "statedApplications": [],
      "openSlots": []
    },
    {
      "id": "R3",
      "ruleQuote": "최소가청강도는 주파수별로 그 크기가 정해져 있다. 예를 들어, 1,000 Hz부터 10,000 Hz 사이에서는 아주 작은 소리도 들을 수 있지만, 100 Hz 이하의 저음에서는 훨씬 큰 소리여야 들을 수 있다.",
      "statement": "최소가청강도는 주파수에 따라 달라지며, 100 Hz 이하에서는 1,000 Hz부터 10,000 Hz 사이에서보다 훨씬 큰 소리여야 들을 수 있다.",
      "variables": [
        {
          "name": "소리의 주파수",
          "effect": "주파수별로 최소가청강도가 다르며, 1,000 Hz부터 10,000 Hz 사이에서는 아주 작은 소리도 들리지만 100 Hz 이하에서는 훨씬 큰 소리여야 들린다."
        }
      ],
      "scopeQuote": "최소가청강도는 조용할 때 청각이 감지할 수 있는 소리 크기의 최솟값이다.",
      "statedApplications": [
        {
          "target": "1,000 Hz부터 10,000 Hz 사이의 소리",
          "quote": "1,000 Hz부터 10,000 Hz 사이에서는 아주 작은 소리도 들을 수 있지만"
        },
        {
          "target": "100 Hz 이하의 저음",
          "quote": "100 Hz 이하의 저음에서는 훨씬 큰 소리여야 들을 수 있다."
        }
      ],
      "openSlots": []
    },
    {
      "id": "R4",
      "ruleQuote": "두 소리의 주파수가 가까울수록 차폐가 쉽게 일어나고, 주파수가 어느 정도 차이가 나면 차폐가 일어나지 않는다.",
      "statement": "큰 소리와 작은 소리의 주파수가 가까울수록 차폐가 쉽게 일어나며, 주파수가 어느 정도 차이 나면 차폐가 일어나지 않는다.",
      "variables": [
        {
          "name": "두 소리의 주파수 차이",
          "effect": "주파수 차이가 작을수록 차폐가 쉽게 일어나고, 어느 정도 차이가 나면 차폐가 일어나지 않는다."
        }
      ],
      "scopeQuote": "큰 소리로 인해 작은 소리가 들리지 않는 현상을 차폐라고 하며",
      "statedApplications": [],
      "openSlots": []
    },
    {
      "id": "R5",
      "ruleQuote": "임계대역의 폭은 차폐음의 주파수에 따라 다른데 고음에서는 저음에서보다 임계대역이 훨씬 넓다.",
      "statement": "차폐음의 주파수에 따라 임계대역의 폭이 달라지며, 고음의 임계대역은 저음의 임계대역보다 훨씬 넓다.",
      "variables": [
        {
          "name": "차폐음의 주파수",
          "effect": "차폐음이 고음일 때의 임계대역은 저음일 때보다 훨씬 넓다."
        }
      ],
      "scopeQuote": null,
      "statedApplications": [],
      "openSlots": []
    },
    {
      "id": "R6",
      "ruleQuote": "소리 크기와 차폐 문턱값의 차이가 큰 소리일수록 해당 소리 크기에 비트를 많이 할당하여 소리의 손실을 낮춘다.",
      "statement": "지각부호화에서는 소리 크기와 차폐 문턱값의 차이가 큰 소리일수록 비트를 많이 할당하여 소리의 손실을 낮춘다.",
      "variables": [
        {
          "name": "소리 크기와 차폐 문턱값의 차이",
          "effect": "차이가 큰 소리일수록 해당 소리 크기에 비트를 많이 할당하여 소리의 손실을 낮춘다."
        }
      ],
      "scopeQuote": "지각부호화에서는 오디오 신호를 먼저 주파수에 따라 여러 개의 임계대역으로 나누고, 각 임계대역에서 최소가청강도와 차폐음을 고려하여 차폐 문턱값을 구한다.",
      "statedApplications": [],
      "openSlots": []
    },
    {
      "id": "R7",
      "ruleQuote": "차폐 문턱값보다 작은 소리들은 들리지 않으므로 제거한다.",
      "statement": "지각부호화에서는 소리 크기가 차폐 문턱값보다 작으면 들리지 않는 소리로 보아 제거한다.",
      "variables": [
        {
          "name": "차폐 문턱값에 대한 소리 크기의 대소 관계",
          "effect": "소리 크기가 차폐 문턱값보다 작으면 들리지 않으므로 제거한다."
        }
      ],
      "scopeQuote": "지각부호화에서는 오디오 신호를 먼저 주파수에 따라 여러 개의 임계대역으로 나누고, 각 임계대역에서 최소가청강도와 차폐음을 고려하여 차폐 문턱값을 구한다.",
      "statedApplications": [],
      "openSlots": []
    }
  ]
}

